import { describe, test, expect } from 'bun:test';
import { mkdtemp, readdir, readFile, rm } from 'fs/promises';
import { tmpdir } from 'os';
import { join } from 'path';
import { generate } from '../../scripts/gen-cli-reference';
import { setDocsBaseUrl, resetDocsBaseUrl } from '../../src/docs/links';
import { IMAGE_TAG } from '../../src/capture/image-tag';
import { VERSION } from '../../src/version';

// INVARIANT: every page under public-docs/reference/cli/ is the command's own
// usage text, regenerated byte-for-byte. The page is never hand-written, so it
// cannot drift from the code; a changed usage text without `bun run docs:cli`
// fails here.
describe('generated CLI reference', () => {
  test('committed pages equal a fresh generation', async () => {
    const committed = join(import.meta.dir, '../../public-docs/reference/cli');
    const fresh = await mkdtemp(join(tmpdir(), 'cli-ref-'));
    try {
      await generate(fresh);
      const want = (await readdir(fresh)).sort();
      const have = (await readdir(committed)).filter((f) => f.endsWith('.md')).sort();
      expect(have).toEqual(want);
      for (const f of want) {
        expect(await readFile(join(committed, f), 'utf8')).toBe(await readFile(join(fresh, f), 'utf8'));
      }
    } finally {
      await rm(fresh, { recursive: true, force: true });
    }
  }, 60_000);

  // INVARIANT: no generated page links to a version-pinned docs snapshot. The pages are part of the
  // site they link to, and a pinned URL would go stale (failing the test above) on every minor bump.
  test('pages carry no version-pinned docs URL', async () => {
    const dir = join(import.meta.dir, '../../public-docs/reference/cli');
    for (const f of (await readdir(dir)).filter((x) => x.endsWith('.md'))) {
      expect(await readFile(join(dir, f), 'utf8')).not.toMatch(/docs\.getlazy\.dev\/v\d+\.\d+\//);
    }
  });

  // INVARIANT: no generated page names this build's version or runner image tag. Either would change
  // on the next release and fail the byte-for-byte test above on the release commit.
  test('pages carry no build version or image tag', async () => {
    const dir = join(import.meta.dir, '../../public-docs/reference/cli');
    for (const f of (await readdir(dir)).filter((x) => x.endsWith('.md'))) {
      const body = await readFile(join(dir, f), 'utf8');
      expect(body).not.toContain(VERSION);
      expect(body).not.toContain(`lazy-runner:${IMAGE_TAG}`);
    }
  });

  // INVARIANT: generation always uses the built-in docs base. The pages must not depend on the
  // generating environment's configuration, so a configured `[docs] url` can never leak in.
  test('a configured docs url does not leak into generated pages', async () => {
    const fresh = await mkdtemp(join(tmpdir(), 'cli-ref-docsurl-'));
    try {
      setDocsBaseUrl('https://mirror.example.test/docs');
      await generate(fresh);
      for (const f of (await readdir(fresh)).filter((x) => x.endsWith('.md'))) {
        expect(await readFile(join(fresh, f), 'utf8')).not.toContain('mirror.example.test');
      }
      expect(await readFile(join(fresh, 'accept.md'), 'utf8')).toContain('Documentation: https://docs.getlazy.dev/raised-items');
    } finally {
      resetDocsBaseUrl();
      await rm(fresh, { recursive: true, force: true });
    }
  }, 60_000);
});
